70: void us_internal_loop_unlink(struct us_loop_t *loop, struct us_socket_context_t *context) {
71:     if (loop->data.head == context) {
72:         loop->data.head = context->next;
73:         if (loop->data.head) {
74:             loop->data.head->prev = 0;
75:         }
76:     } else {
77:         context->prev->next = context->next;
78:         if (context->next) {
79:             context->next->prev = context->prev;
80:         }
81:     }
