145: void us_internal_handle_low_priority_sockets(struct us_loop_t *loop) {
146:     struct us_internal_loop_data_t *loop_data = &loop->data;
147:     struct us_socket_t *s;
148: 
149:     loop_data->low_prio_budget = MAX_LOW_PRIO_SOCKETS_PER_LOOP_ITERATION;
150: 
151:     for (s = loop_data->low_prio_head; s && loop_data->low_prio_budget > 0; s = loop_data->low_prio_head, loop_data->low_prio_budget--) {
152:         /* Unlink this socket from the low-priority queue */
153:         loop_data->low_prio_head = s->next;
154:         if (s->next) s->next->prev = 0;
155:         s->next = 0;
156: 
157:         us_internal_socket_context_link_socket(s->context, s);
158:         us_poll_change(&s->p, us_socket_context(0, s)->loop, us_poll_events(&s->p) | LIBUS_SOCKET_READABLE);
159: 
160:         s->low_prio_state = 2;
161:     }
162: }
