225: void us_internal_dispatch_ready_poll(struct us_poll_t *p, int error, int events) {
226:     switch (us_internal_poll_type(p)) {
227:     case POLL_TYPE_CALLBACK: {
228:             struct us_internal_callback_t *cb = (struct us_internal_callback_t *) p;
229:             /* Timers, asyncs should accept (read), while UDP sockets should obviously not */
230:             if (!cb->leave_poll_ready) {
231:                 /* Let's just have this macro to silence the CodeQL alert regarding empty function when using libuv */
232:     #ifndef LIBUS_USE_LIBUV
233:                 us_internal_accept_poll_event(p);
234:     #endif
235:             }
236:             cb->cb(cb->cb_expects_the_loop ? (struct us_internal_callback_t *) cb->loop : (struct us_internal_callback_t *) &cb->p);
237:         }
238:         break;
239:     case POLL_TYPE_SEMI_SOCKET: {
240:             /* Both connect and listen sockets are semi-sockets
241:              * but they poll for different events */
242:             if (us_poll_events(p) == LIBUS_SOCKET_WRITABLE) {
243:                 struct us_socket_t *s = (struct us_socket_t *) p;
244: 
245:                 /* It is perfectly possible to come here with an error */
