30: /* This functions should never run recursively */
31: void us_internal_timer_sweep(struct us_loop_t *loop) {
32:     struct us_loop_t *loop_data = loop;
33:     /* For all socket contexts in this loop */
34:     for (loop_data->iterator = loop_data->head; loop_data->iterator; loop_data->iterator = loop_data->iterator->next) {
35: 
36: 
37:         struct us_socket_context_t *context = loop_data->iterator;
38: 
39:         /* Update this context's timestamps (this could be moved to loop and done once) */
40:         context->global_tick++;
41:         unsigned char short_ticks = context->timestamp = context->global_tick % 240;
42:         unsigned char long_ticks = context->long_timestamp = (context->global_tick / 15) % 240;
43: 
44:         /* Begin at head */
45:         struct us_socket_t *s = context->head_sockets;
46:         while (s) {
47:             /* Seek until end or timeout found (tightest loop) */
48:             while (1) {
49:                 /* We only read from 1 random cache line here */
50:                 if (short_ticks == s->timeout || long_ticks == s->long_timeout) {
51:                     break;
52:                 }
53: 
54:                 /* Did we reach the end without a find? */
55:                 if ((s = s->next) == 0) {
56:                     goto next_context;
57:                 }
58:             }
59: 
60:             /* Here we have a timeout to emit (slow path) */
61:             context->iterator = s;
62: 
63:             if (short_ticks == s->timeout) {
64:                 s->timeout = 255;
65:                 context->on_socket_timeout(s);
66:             }
67: 
68:             if (context->iterator == s && long_ticks == s->long_timeout) {
69:                 s->long_timeout = 255;
70:                 context->on_socket_long_timeout(s);
71:             }   
72: 
73:             /* Check for unlink / link (if the event handler did not modify the chain, we step 1) */
74:             if (s == context->iterator) {
75:                 s = s->next;
76:             } else {
77:                 /* The iterator was changed by event handler */
78:                 s = context->iterator;
79:             }
80:         }
81:         /* We always store a 0 to context->iterator here since we are no longer iterating this context */
82:         next_context:
83:         context->iterator = 0;
84:     }
85: }
